    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = ModuloPeer::MODULO_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(ModuloPeer::MODULO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . ModuloPeer::MODULO_ID . ')');
