    protected function doAddWebserviceReply($webserviceReply)
    {
        $this->collWebserviceReplys[]= $webserviceReply;
        $webserviceReply->setModulo($this);
    }

    /**
     * @param	WebserviceReply $webserviceReply The webserviceReply object to remove.
     * @return Modulo The current object (for fluent API support)
     */
    public function removeWebserviceReply($webserviceReply)
    {
        if ($this->getWebserviceReplys()->contains($webserviceReply)) {
            $this->collWebserviceReplys->remove($this->collWebserviceReplys->search($webserviceReply));
            if (null === $this->webserviceReplysScheduledForDeletion) {
                $this->webserviceReplysScheduledForDeletion = clone $this->collWebserviceReplys;
                $this->webserviceReplysScheduledForDeletion->clear();
            }
            $this->webserviceReplysScheduledForDeletion[]= clone $webserviceReply;
            $webserviceReply->setModulo(null);
        }

        return $this;
    }


    /**
     * If this collection has already been initialized with
     * an identical criteria, it returns the collection.
     * Otherwise if this Modulo is new, it will return
     * an empty collection; or if this Modulo has previously
     * been saved, it will retrieve related WebserviceReplys from storage.
     *
     * This method is protected by default in order to keep the public
     * api reasonable.  You can provide public methods for those you
     * actually need in Modulo.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @param string $join_behavior optional join type to use (defaults to Criteria::LEFT_JOIN)
     * @return PropelObjectCollection|WebserviceReply[] List of WebserviceReply objects
     */
    public function getWebserviceReplysJoinUsuario($criteria = null, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $query = WebserviceReplyQuery::create(null, $criteria);
        $query->joinWith('Usuario', $join_behavior);

        return $this->getWebserviceReplys($query, $con);
    }

    /**
     * Clears out the collFormas collection
     *
     * This does not modify the database; however, it will remove any associated objects, causing
     * them to be refetched by subsequent calls to accessor method.
     *
     * @return Modulo The current object (for fluent API support)
     * @see        addFormas()
     */
    public function clearFormas()
    {
        $this->collFormas = null; // important to set this to null since that means it is uninitialized
        $this->collFormasPartial = null;

        return $this;
    }

    /**
     * reset is the collFormas collection loaded partially
     *
     * @return void
     */
    public function resetPartialFormas($v = true)
    {
        $this->collFormasPartial = $v;
    }

    /**
     * Initializes the collFormas collection.
     *
     * By default this just sets the collFormas collection to an empty array (like clearcollFormas());
     * however, you may wish to override this method in your stub class to provide setting appropriate
     * to your application -- for example, setting the initial array to the values stored in database.
     *
     * @param boolean $overrideExisting If set to true, the method call initializes
     *                                        the collection even if it is not empty
     *
     * @return void
     */
    public function initFormas($overrideExisting = true)
    {
        if (null !== $this->collFormas && !$overrideExisting) {
            return;
        }
        $this->collFormas = new PropelObjectCollection();
        $this->collFormas->setModel('Forma');
    }

    /**
     * Gets an array of Forma objects which contain a foreign key that references this object.
     *
     * If the $criteria is not null, it is used to always fetch the results from the database.
     * Otherwise the results are fetched from the database the first time, then cached.
     * Next time the same method is called without $criteria, the cached collection is returned.
     * If this Modulo is new, it will return
     * an empty collection or the current collection; the criteria is ignored on a new object.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @return PropelObjectCollection|Forma[] List of Forma objects
     * @throws PropelException
     */
    public function getFormas($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collFormasPartial && !$this->isNew();
        if (null === $this->collFormas || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collFormas) {
                // return empty collection
                $this->initFormas();
            } else {
                $collFormas = FormaQuery::create(null, $criteria)
                    ->filterByModulo($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collFormasPartial && count($collFormas)) {
                      $this->initFormas(false);

                      foreach ($collFormas as $obj) {
                        if (false == $this->collFormas->contains($obj)) {
                          $this->collFormas->append($obj);
                        }
                      }

                      $this->collFormasPartial = true;
                    }

                    $collFormas->getInternalIterator()->rewind();

                    return $collFormas;
                }

                if ($partial && $this->collFormas) {
                    foreach ($this->collFormas as $obj) {
                        if ($obj->isNew()) {
                            $collFormas[] = $obj;
                        }
                    }
                }

                $this->collFormas = $collFormas;
                $this->collFormasPartial = false;
            }
        }

        return $this->collFormas;
    }

    /**
     * Sets a collection of Forma objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $formas A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return Modulo The current object (for fluent API support)
     */
    public function setFormas(PropelCollection $formas, PropelPDO $con = null)
    {
        $formasToDelete = $this->getFormas(new Criteria(), $con)->diff($formas);


        $this->formasScheduledForDeletion = $formasToDelete;

        foreach ($formasToDelete as $formaRemoved) {
            $formaRemoved->setModulo(null);
        }

        $this->collFormas = null;
        foreach ($formas as $forma) {
            $this->addForma($forma);
        }

        $this->collFormas = $formas;
        $this->collFormasPartial = false;

        return $this;
    }

    /**
     * Returns the number of related Forma objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related Forma objects.
     * @throws PropelException
     */
    public function countFormas(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collFormasPartial && !$this->isNew();
        if (null === $this->collFormas || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collFormas) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getFormas());
            }
            $query = FormaQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByModulo($this)
                ->count($con);
        }

        return count($this->collFormas);
    }

    /**
     * Method called to associate a Forma object to this object
     * through the Forma foreign key attribute.
     *
     * @param    Forma $l Forma
     * @return Modulo The current object (for fluent API support)
     */
    public function addForma(Forma $l)
    {
        if ($this->collFormas === null) {
            $this->initFormas();
            $this->collFormasPartial = true;
        }

        if (!in_array($l, $this->collFormas->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddForma($l);

            if ($this->formasScheduledForDeletion and $this->formasScheduledForDeletion->contains($l)) {
                $this->formasScheduledForDeletion->remove($this->formasScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	Forma $forma The forma object to add.
     */
    protected function doAddForma($forma)
    {
        $this->collFormas[]= $forma;
        $forma->setModulo($this);
    }

    /**
     * @param	Forma $forma The forma object to remove.
     * @return Modulo The current object (for fluent API support)
     */
    public function removeForma($forma)
    {
        if ($this->getFormas()->contains($forma)) {
            $this->collFormas->remove($this->collFormas->search($forma));
            if (null === $this->formasScheduledForDeletion) {
                $this->formasScheduledForDeletion = clone $this->collFormas;
                $this->formasScheduledForDeletion->clear();
            }
            $this->formasScheduledForDeletion[]= clone $forma;
            $forma->setModulo(null);
        }

        return $this;
    }

    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->modulo_id = null;
        $this->descripcion = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collReceptors) {
                foreach ($this->collReceptors as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collReceptorComunicacioness) {
                foreach ($this->collReceptorComunicacioness as $o) {
                    $o->clearAllReferences($deep);
                }
