                }
            }
            if ($this->collAuditLogs) {
                foreach ($this->collAuditLogs as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWsUsuariosModulos) {
                foreach ($this->collWsUsuariosModulos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collAutorizacionFirmas) {
                foreach ($this->collAutorizacionFirmas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collPlantillasComs) {
                foreach ($this->collPlantillasComs as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collServicios) {
                foreach ($this->collServicios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTipoNotificacions) {
                foreach ($this->collTipoNotificacions as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComMigmasivos) {
                foreach ($this->collComMigmasivos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTipoControls) {
                foreach ($this->collTipoControls as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComAprobacions) {
                foreach ($this->collComAprobacions as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWebserviceReplys) {
                foreach ($this->collWebserviceReplys as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collFormas) {
                foreach ($this->collFormas as $o) {
                    $o->clearAllReferences($deep);
                }
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collReceptors instanceof PropelCollection) {
            $this->collReceptors->clearIterator();
        }
        $this->collReceptors = null;
        if ($this->collReceptorComunicacioness instanceof PropelCollection) {
            $this->collReceptorComunicacioness->clearIterator();
        }
        $this->collReceptorComunicacioness = null;
        if ($this->collNovedadess instanceof PropelCollection) {
            $this->collNovedadess->clearIterator();
        }
        $this->collNovedadess = null;
        if ($this->collAuditLogs instanceof PropelCollection) {
            $this->collAuditLogs->clearIterator();
        }
        $this->collAuditLogs = null;
        if ($this->collWsUsuariosModulos instanceof PropelCollection) {
            $this->collWsUsuariosModulos->clearIterator();
        }
        $this->collWsUsuariosModulos = null;
        if ($this->collAutorizacionFirmas instanceof PropelCollection) {
            $this->collAutorizacionFirmas->clearIterator();
        }
        $this->collAutorizacionFirmas = null;
        if ($this->collPlantillasComs instanceof PropelCollection) {
            $this->collPlantillasComs->clearIterator();
        }
        $this->collPlantillasComs = null;
        if ($this->collServicios instanceof PropelCollection) {
